static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ScatterAddCustomTilingData tiling;

    const auto* x_shape = context->GetInputShape(0);
    const auto* idx_shape = context->GetInputShape(1);

    uint32_t rows = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(0));
    uint32_t cols = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(1));
    uint32_t k = static_cast<uint32_t>(idx_shape->GetOriginShape().GetDim(1));

    // 设置每个block处理一行
    context->SetBlockDim(rows);

    // 简单分块策略：按列与K方向做固定分块
    uint32_t rowTile = cols >= 1024 ? 1024 : cols;
    uint32_t kTile = k >= 1024 ? 1024 : k;

    tiling.set_rows(rows);
    tiling.set_cols(cols);
    tiling.set_k(k);
    tiling.set_rowTile(rowTile);
    tiling.set_kTile(kTile);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0; // 无需workspace
    return ge::GRAPH_SUCCESS;
}
}

